-- ============================================================================
--  BUILD WITH US  —  materials, contractors, designs & designers
--  Run this ONCE in the Supabase SQL editor (project ioblbfugnhtghvxbyeos).
--  Creates + seeds the four catalogs the consumer "Build With Us" page and the
--  admin panel share, with permissive RLS (matching the other tables).
--
--  NOTE: columns the JS reads in camelCase ("priceUnit", "priceFrom") are quoted
--  so PostgREST returns them with the exact key the app expects. Array fields
--  (tags / styles / scope / portfolio / types) are jsonb.
--
--  The consumer site shows the static bundled catalog until a table has rows;
--  once seeded here, admin edits persist and surface on the live site.
-- ============================================================================
SET search_path = public;
DO $img$ BEGIN END $img$;  -- no-op marker

-- helper note: image base = https://images.unsplash.com/photo-<id>?w=600&h=400&fit=crop

-- ───────────────────────── Materials & Hardware ─────────────────────────
CREATE TABLE IF NOT EXISTS public.build_materials (
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        text NOT NULL,
  category    text,
  brand       text,
  supplier    text,
  unit        text,
  price       numeric,
  stock       text,
  image       text,
  description text,
  types       jsonb,
  created_at  timestamptz DEFAULT now()
);

