-- ───── Row-Level Security — permissive (anon read+write), matching other tables ─────
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['build_materials','build_services','build_designs','build_designers'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;', t);
    EXECUTE format('DROP POLICY IF EXISTS "anon_all_%1$s" ON public.%1$I;', t);
    EXECUTE format('CREATE POLICY "anon_all_%1$s" ON public.%1$I FOR ALL USING (true) WITH CHECK (true);', t);
  END LOOP;
END $$;

-- ───── Bump identity sequences past the seeded ids so admin inserts don't collide ─────
SELECT setval(pg_get_serial_sequence('public.build_materials','id'), COALESCE((SELECT MAX(id) FROM public.build_materials), 1));
SELECT setval(pg_get_serial_sequence('public.build_services','id'),  COALESCE((SELECT MAX(id) FROM public.build_services),  1));
SELECT setval(pg_get_serial_sequence('public.build_designs','id'),   COALESCE((SELECT MAX(id) FROM public.build_designs),   1));
SELECT setval(pg_get_serial_sequence('public.build_designers','id'), COALESCE((SELECT MAX(id) FROM public.build_designers), 1));

-- Done. The consumer "Build With Us" page now reads these tables (falling back to
-- the bundled catalog if a table is empty/missing), and admin-panel edits persist.
